SELECT "major" 
FROM "student" 
WHERE "first_name" = 'Angela' AND "last_name" = 'Sanders';

SELECT "notes" 
FROM "fundraising"
WHERE "date" = '2019-09-14';

SELECT "major" 
FROM "students" 
WHERE "first_name" = 'Brent' AND "last_name" = 'Thomason';

SELECT COUNT(*) 
FROM "cities" 
WHERE "county" = 'Orange County' AND "state" = 'Virginia';

SELECT SUM("amount") AS total_spent
FROM "transactions"
WHERE "category" = 'food';

SELECT 
    (SUM(CASE WHEN "event_name" = 'Yearly Kickoff' THEN "total_cost" ELSE 0 END) * 100.0 / SUM("total_cost")) AS percentage
FROM "events";

SELECT COUNT(*) 
FROM "Student_Club" 
WHERE "major" = 'Physics Teaching';

SELECT "cost"
FROM "posters"
WHERE "event" = 'September Speaker';

SELECT SUM("amount") AS total_expense
FROM "expenses"
WHERE "date" = '2019-08-20';

SELECT DISTINCT "category"
FROM "events"
WHERE "location" = 'MU 215';
